const {
  computePriority,
  scoreBreakdown,
  minutesWaiting,
  waitingPoints,
  complexityPoints,
  promisePoints,
  vipPoints,
} = require('../../../src/modules/orders/priority');
const { DomainError } = require('../../../src/modules/orders/errors');

const NOW = new Date('2026-01-15T12:00:00.000Z');
const minus = (ms) => new Date(NOW.getTime() - ms);
const plus = (ms) => new Date(NOW.getTime() + ms);
const SEC = 1000;
const MIN = 60 * SEC;

describe('minutesWaiting', () => {
  test('uses whole minutes (9m50s counts as 9)', () => {
    expect(minutesWaiting({ placed_at: minus(9 * MIN + 50 * SEC) }, NOW)).toBe(9);
  });

  test('clamps future placed_at to zero', () => {
    expect(minutesWaiting({ placed_at: plus(5 * MIN) }, NOW)).toBe(0);
  });

  test('accepts ISO strings', () => {
    expect(minutesWaiting({ placed_at: minus(12 * MIN).toISOString() }, NOW)).toBe(12);
  });
});

describe('waitingPoints', () => {
  test.each([
    [0, 0],
    [9 * MIN + 50 * SEC, 0],
    [10 * MIN, 5],
    [25 * MIN, 10],
    [79 * MIN, 35],
    [80 * MIN, 40],
    [300 * MIN, 40],
  ])('waited %pms -> %p points', (waitedMs, points) => {
    expect(waitingPoints({ placed_at: minus(waitedMs) }, NOW)).toBe(points);
  });

  test('cap: never exceeds 40', () => {
    expect(waitingPoints({ placed_at: minus(24 * 60 * MIN) }, NOW)).toBe(40);
  });
});

describe('complexityPoints', () => {
  test.each([
    [0, 0],
    [14, 0],
    [15, 5],
    [30, 10],
    [59, 15],
    [60, 20],
    [120, 20],
  ])('%p complexity minutes -> %p points', (minutes, points) => {
    expect(complexityPoints({ complexity_minutes: minutes })).toBe(points);
  });

  test('cap: never exceeds 20', () => {
    expect(complexityPoints({ complexity_minutes: 1000 })).toBe(20);
  });
});

describe('promisePoints (exact time difference)', () => {
  test.each([
    ['overdue', minus(5 * MIN), 25],
    ['due now', NOW, 25],
    ['due in 30:00', plus(30 * MIN), 25],
    ['due in 30:30', plus(30 * MIN + 30 * SEC), 15],
    ['due in 60:00', plus(60 * MIN), 15],
    ['due in 61:00', plus(61 * MIN), 0],
    ['no promise (null)', null, 0],
  ])('%s', (_label, promisedAt, points) => {
    expect(promisePoints({ promised_at: promisedAt }, NOW)).toBe(points);
  });
});

describe('vipPoints', () => {
  test('VIP adds 20, non-VIP adds 0', () => {
    expect(vipPoints({ is_vip: true })).toBe(20);
    expect(vipPoints({ is_vip: false })).toBe(0);
  });
});

describe('computePriority', () => {
  test('rejects unknown order types with a DomainError', () => {
    expect(() => computePriority({ type: 'nope', placed_at: NOW }, NOW)).toThrow(DomainError);
    try {
      computePriority({ type: 'nope', placed_at: NOW }, NOW);
    } catch (err) {
      expect(err.code).toBe('UNKNOWN_ORDER_TYPE');
    }
  });

  test('does not read the clock: same input, same output', () => {
    const spy = jest.spyOn(Date, 'now');
    expect(() => scoreBreakdown).not.toThrow();
    expect(spy).not.toHaveBeenCalled();
    spy.mockRestore();
  });

  // PENDING: needs the order-type points and worked examples from the assignment brief,
  // which was not available in the repository when these tests were written.
  test.todo('worked example A scores 60');
  test.todo('worked example B scores 60 and sorts ahead of A');
  test.todo('delivery VIP order outranks non-VIP dine-in order');
});
EOF
cat > compareQueue.test.js <<'EOF'
const { COMPARATORS, compareQueue } = require('../../../src/modules/orders/compareQueue');

const at = (iso) => new Date(iso);
const base = {
  score: 50,
  promised_at: at('2026-01-15T12:30:00Z'),
  placed_at: at('2026-01-15T11:00:00Z'),
  id: 10,
};
const ids = (list) => list.map((o) => o.id);

describe('compareQueue', () => {
  test('comparators are an ordered list', () => {
    expect(COMPARATORS.map((c) => c.name)).toEqual([
      'byScoreDesc',
      'byPromisedAtAscNullsLast',
      'byPlacedAtAsc',
      'byIdAsc',
    ]);
  });

  test('1. higher score first', () => {
    const a = { ...base, id: 1, score: 40 };
    const b = { ...base, id: 2, score: 60 };
    expect(ids([a, b].sort(compareQueue))).toEqual([2, 1]);
  });

  test('2. equal score: earlier promised_at first', () => {
    const a = { ...base, id: 1, promised_at: at('2026-01-15T12:45:00Z') };
    const b = { ...base, id: 2, promised_at: at('2026-01-15T12:15:00Z') };
    expect(ids([a, b].sort(compareQueue))).toEqual([2, 1]);
  });

  test('2. equal score: null promised_at sorts last', () => {
    const a = { ...base, id: 1, promised_at: null };
    const b = { ...base, id: 2, promised_at: at('2026-01-15T23:00:00Z') };
    expect(ids([a, b].sort(compareQueue))).toEqual([2, 1]);
  });

  test('3. equal score and promise: earlier placed_at first', () => {
    const a = { ...base, id: 1, placed_at: at('2026-01-15T11:30:00Z') };
    const b = { ...base, id: 2, placed_at: at('2026-01-15T11:10:00Z') };
    expect(ids([a, b].sort(compareQueue))).toEqual([2, 1]);
  });

  test('3. both promises null: falls through to placed_at', () => {
    const a = { ...base, id: 1, promised_at: null, placed_at: at('2026-01-15T11:30:00Z') };
    const b = { ...base, id: 2, promised_at: null, placed_at: at('2026-01-15T11:10:00Z') };
    expect(ids([a, b].sort(compareQueue))).toEqual([2, 1]);
  });

  test('4. everything equal: lower id first', () => {
    const a = { ...base, id: 7 };
    const b = { ...base, id: 3 };
    expect(ids([a, b].sort(compareQueue))).toEqual([3, 7]);
  });

  test('full tie-break sequence on one list', () => {
    const list = [
      { ...base, id: 6 }, // ties with 5 except id
      { ...base, id: 5 },
      { ...base, id: 4, placed_at: at('2026-01-15T10:00:00Z') },
      { ...base, id: 3, promised_at: null },
      { ...base, id: 2, promised_at: at('2026-01-15T12:10:00Z') },
      { ...base, id: 1, score: 70 },
    ];
    expect(ids(list.sort(compareQueue))).toEqual([1, 2, 4, 5, 6, 3]);
  });
});
