  border-radius: 10px;
  background: var(--panel);
  padding: 16px;
}

.panel__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.error-banner {
  margin-bottom: 16px;
}

.error-banner__message {
  display: block;
}

