  color: var(--muted);
  font-size: 11px;
}

.columns__lane {
  display: flex;
  justify-content: space-between;
}

.columns__pass {
  color: var(--heat);
  transform: translateX(50%);
}

.columns__wait {
  text-align: right;
}

.rows {
  position: relative;
}

.row {
  position: relative;
  padding: var(--row-pad);
  margin-bottom: var(--row-gap);
  border: 1px solid transparent;
  border-radius: 10px;
}

.row--next {
  border-color: rgb(255 75 62 / 0.75);
  box-shadow:
    0 0 0 1px rgb(255 75 62 / 0.25),
    0 0 24px rgb(255 75 62 / 0.22);
}

/* Order-type tile */
.type-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.type-tile__icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid var(--card-line);
  border-radius: 8px;
  background: var(--card);
  color: var(--text);
}

.type-tile__label {
  font-size: 10px;
  color: var(--muted);
  white-space: nowrap;
}

/* Order card */
.card {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas:
    'head score'
    'items score';
  column-gap: 12px;
  row-gap: 4px;
  padding: 10px 12px;
  border: 1px solid var(--card-line);
  border-radius: 8px;
  background: var(--card);
  overflow: hidden;
}

.card__flash {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: rgb(255 179 65 / 0.18);
  box-shadow: inset 0 0 0 1px var(--heat);
  animation: card-flash 1.2s ease-out forwards;
}

@keyframes card-flash {
  from { opacity: 1; }
  to { opacity: 0; }
}

.card__head {
  grid-area: head;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.card__name {
  font-size: 15px;
  font-weight: 600;
  margin-right: 2px;
}

.card__items {
  grid-area: items;
  margin: 0;
  font-size: 12px;
  line-height: 1.45;
  color: var(--muted);
}

.card__score {
  grid-area: score;
  align-self: center;
  display: flex;
  align-items: baseline;
  gap: 3px;
  cursor: help;
}

.card__score-value {
  font-size: 22px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--heat);
}

.card__score-unit {
  font-size: 11px;
  color: var(--muted);
}

.badge {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  border: 1px solid var(--card-line);
  color: var(--muted);
}

.badge--vip {
  color: var(--heat);
  border-color: rgb(255 179 65 / 0.55);
}

.badge--preparing {
  color: var(--text);
  border-color: #3a4049;
  background: #1b1f24;
}

.badge--next {
  color: var(--alarm);
  border-color: rgb(255 75 62 / 0.5);
}

/* Lane: the ball travels right toward the pass as its score approaches the top score. */
.lane {
  position: relative;
  align-self: stretch;
  min-height: 56px;
}

.lane__track {
  position: absolute;
  left: 0;
  right: 0;
  top: 60%;
  height: 1px;
  background: repeating-linear-gradient(
    to right,
    var(--card-line) 0 6px,
    transparent 6px 12px
  );
}

.lane__ball {
  position: absolute;
  top: 0;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #fff3d6 0%, var(--heat) 45%, #c47a12 100%);
  box-shadow:
    0 0 10px rgb(255 179 65 / 0.8),
    0 0 26px rgb(255 179 65 / 0.35);
}

.lane__pass {
  position: absolute;
  right: 0;
  top: calc(-1 * (var(--row-pad) + var(--row-gap) / 2 + 1px));
  bottom: calc(-1 * (var(--row-pad) + var(--row-gap) / 2 + 1px));
  width: 2px;
  margin-right: -1px;
  background: var(--heat);
  box-shadow: 0 0 12px rgb(255 179 65 / 0.55);
  opacity: 0.85;
}

.lane__promise {
  position: absolute;
  right: 10px;
  top: 4px;
  font-size: 11px;
  color: var(--muted);
  white-space: nowrap;
}

.lane__promise--late {
  color: var(--alarm);
  font-weight: 600;
}

/* Waiting time and actions */
.wait {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.wait__value {
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.wait__label {
  font-size: 10px;
  color: var(--muted);
}

.actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.actions__cancel {
  color: var(--muted);
}

.empty {
  padding: 48px 16px;
  text-align: center;
  border: 1px dashed var(--line);
  border-radius: 10px;
}

.empty__title {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 600;
}

.empty__hint {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

:focus-visible {
  outline: 2px solid var(--heat);
  outline-offset: 2px;
}

@media (max-width: 980px) {
  .columns {
    display: none;
  }
  .row {
    grid-template-columns: 52px 1fr auto;
    grid-template-areas:
      'tile card card'
      'lane lane lane'
      'wait wait actions';
    row-gap: 10px;
    border-color: var(--line);
  }
  .row--next {
    border-color: rgb(255 75 62 / 0.75);
  }
  .type-tile { grid-area: tile; }
  .card { grid-area: card; }
  .lane { grid-area: lane; min-height: 44px; }
  .lane__pass { top: 0; bottom: 0; }
  .wait { grid-area: wait; flex-direction: row; align-items: baseline; gap: 6px; }
  .actions { grid-area: actions; }
}

@media (max-width: 520px) {
  .kd { padding: 20px 16px 32px; }
  .kd__title { font-size: 22px; }
  .panel { padding: 12px; }
  .panel__toolbar { flex-wrap: wrap; }
}

@media (prefers-reduced-motion: reduce) {
  .card__flash {
    animation-duration: 0.01s;
    animation-delay: 1s;
  }
}
EOF
